                "Fatura de hospedagem nº " + id + "\\nEmpresa: Tecnosul Ltda (CNPJ 12.345.678\/0001-90)\\n"
                        + "Hóspede: Ana Souza\\nQuarto: 201 (DELUXE)\\n"
                        + "Entrada: 10\/03\/2027 | Saída: 12\/03\/2027 | 2 diárias\\n"
                        + "Diárias: R\$ 779,80\\nTotal: R\$ 779,80\\nISS retido (5%): R\$ 38,99\\n",
                document.get("text").asText());
        assertTrue(json.readTree(get("\/messages").body()).get(0).get("body").asText().contains("ISS retido"));
    }

    \@Test
    void foreignerGetsABookingReceipt() throws Exception {
        String body = reservationWith(201, "\\"guestPassport\\": \\"X1234567\\", \\"guestCountry\\": \\"United Kingdom\\",");
        long id = json.readTree(post("\/reservations", body).body()).get("id").asLong();
        post("\/reservations\/" + id + "\/confirmation", "");

        JsonNode document = json.readTree(get("\/reservations\/" + id + "\/document").body());
        assertEquals("Booking receipt", document.get("title").asText());
        assertEquals("United Kingdom", document.get("guestCountry").asText());
        assertEquals(
                "Booking receipt no. " + id + "\\nGuest: Ana Souza (passport X1234567, United Kingdom)\\n"
                        + "Room: 201 (DELUXE)\\nCheck-in: 2027-03-10 | Check-out: 2027-03-12 | 2 nights\\n"
                        + "Nights: BRL 779.80\\nTotal: BRL 779.80\\n",
                document.get("text").asText());
    }

    \@Test
    void theGuestMustBeIdentifiedInExactlyOneWay() throws Exception {
        for (String identification : new String[] {
                "",
                "\\"companyCnpj\\": \\"1\\",",
                "\\"companyName\\": \\"Tecnosul\\",",
                "\\"guestPassport\\": \\"X1\\",",
                "\\"guestCountry\\": \\"Chile\\",",
                "\\"guestCpf\\": \\"1\\", \\"guestPassport\\": \\"X1\\", \\"guestCountry\\": \\"Chile\\",",
                "\\"guestCpf\\": \\"1\\", \\"companyCnpj\\": \\"1\\", \\"companyName\\": \\"T\\",",
                "\\"companyCnpj\\": \\"1\\", \\"companyName\\": \\"T\\", \\"guestPassport\\": \\"X1\\", \\"guestCountry\\": \\"C\\","}) {
            HttpResponse<String> response = post("\/reservations", reservationWith(201, identification));
            assertEquals(400, response.statusCode(), identification);
            assertEquals("INVALID_REQUEST", json.readTree(response.body()).get("error").asText());
        }
